sql_query:
SELECT produce_name AS PRODUCE_NAME, SUM(sales) AS "Total Sales"
FROM tiger_data_engineering.global_superstore_gold.gold_orders
WHERE {SLICER_CONDITIONS}
GROUP BY produce_name
ORDER BY SUM(sales) DESC
LIMIT 10;

SELECT ship_mode AS SHIP_MODE,
       COUNT(DISTINCT order_id) AS "Total Orders"
FROM tiger_data_engineering.global_superstore_gold.gold_orders
WHERE {SLICER_CONDITIONS}
GROUP BY ship_mode
ORDER BY "Total Orders" DESC;
